// src/lib/shopify.ts
import { createStorefrontApiClient } from "@shopify/storefront-api-client";

const client = createStorefrontApiClient({
  storeDomain: process.env.SHOPIFY_STORE_DOMAIN!,
  apiVersion: "2025-01",
  publicAccessToken: process.env.SHOPIFY_STOREFRONT_ACCESS_TOKEN!,
});

const PRODUCT_FRAGMENT = `
  fragment ProductFields on Product {
    id
    title
    handle
    description
    priceRange {
      minVariantPrice {
        amount
        currencyCode
      }
    }
    images(first: 4) {
      edges {
        node {
          url
          altText
          width
          height
        }
      }
    }
    variants(first: 10) {
      edges {
        node {
          id
          title
          availableForSale
          price {
            amount
            currencyCode
          }
        }
      }
    }
  }
`;

export async function getProducts() {
  const { data } = await client.request(
    `query { products(first: 20) { edges { node { ...ProductFields } } } } ${PRODUCT_FRAGMENT}`
  );
  return data?.products.edges.map((edge: { node: unknown }) => edge.node) ?? [];
}

export async function getProductByHandle(handle: string) {
  const { data } = await client.request(
    `query($handle: String!) { product(handle: $handle) { ...ProductFields } } ${PRODUCT_FRAGMENT}`,
    { variables: { handle } }
  );
  return data?.product ?? null;
}

// src/app/products/page.tsx
import Image from "next/image";
import Link from "next/link";
import { getProducts } from "@/lib/shopify";

export const metadata = {
  title: "Products | My Store",
  description: "Browse our collection of products.",
};

export default async function ProductsPage() {
  const products = await getProducts();

  return (
    <main className="mx-auto max-w-7xl px-4 py-16">
      <h1 className="mb-12 text-4xl font-bold">Products</h1>
      <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
        {products.map((product: any) => (
          <Link
            key={product.id}
            href={`/products/${product.handle}`}
            className="group rounded-lg border p-4 transition hover:shadow-lg"
          >
            {product.images.edges[0] && (
              <Image
                src={product.images.edges[0].node.url}
                alt={product.images.edges[0].node.altText ?? product.title}
                width={400}
                height={400}
                className="aspect-square w-full rounded object-cover"
              />
            )}
            <h2 className="mt-4 text-lg font-semibold group-hover:text-blue-600">
              {product.title}
            </h2>
            <p className="mt-1 text-gray-600">
              ${product.priceRange.minVariantPrice.amount}
            </p>
          </Link>
        ))}
      </div>
    </main>
  );
}

// src/app/products/[handle]/page.tsx
import { getProducts, getProductByHandle } from "@/lib/shopify";
import { notFound } from "next/navigation";
import Image from "next/image";
import { AddToCart } from "@/components/AddToCart";

export async function generateStaticParams() {
  const products = await getProducts();
  return products.map((p: any) => ({ handle: p.handle }));
}

export async function generateMetadata({ params }: { params: { handle: string } }) {
  const product = await getProductByHandle(params.handle);
  if (!product) return {};
  return {
    title: `${product.title} | My Store`,
    description: product.description?.slice(0, 160),
    openGraph: {
      images: product.images.edges[0]?.node.url ? [product.images.edges[0].node.url] : [],
    },
  };
}

export default async function ProductPage({ params }: { params: { handle: string } }) {
  const product = await getProductByHandle(params.handle);
  if (!product) notFound();

  const variants = product.variants.edges.map((e: any) => e.node);

  return (
    <main className="mx-auto max-w-6xl px-4 py-16">
      <div className="grid gap-12 md:grid-cols-2">
        <div className="space-y-4">
          {product.images.edges.map((edge: any, i: number) => (
            <Image
              key={i}
              src={edge.node.url}
              alt={edge.node.altText ?? product.title}
              width={edge.node.width}
              height={edge.node.height}
              className="w-full rounded-lg"
              priority={i === 0}
            />
          ))}
        </div>
        <div>
          <h1 className="text-3xl font-bold">{product.title}</h1>
          <p className="mt-2 text-2xl">
            ${product.priceRange.minVariantPrice.amount}
          </p>
          <p className="mt-4 text-gray-600">{product.description}</p>
          <AddToCart variants={variants} />
        </div>
      </div>
    </main>
  );
}

// src/lib/cart-store.ts
"use client";
import { create } from "zustand";
import { persist } from "zustand/middleware";

export interface CartItem {
  variantId: string;
  title: string;
  variantTitle: string;
  price: number;
  quantity: number;
  image?: string;
}

interface CartStore {
  items: CartItem[];
  addItem: (item: Omit<CartItem, "quantity">) => void;
  removeItem: (variantId: string) => void;
  updateQuantity: (variantId: string, quantity: number) => void;
  clearCart: () => void;
  total: () => number;
}

export const useCartStore = create<CartStore>()(
  persist(
    (set, get) => ({
      items: [],
      addItem: (item) =>
        set((state) => {
          const existing = state.items.find((i) => i.variantId === item.variantId);
          if (existing) {
            return {
              items: state.items.map((i) =>
                i.variantId === item.variantId
                  ? { ...i, quantity: i.quantity + 1 }
                  : i
              ),
            };
          }
          return { items: [...state.items, { ...item, quantity: 1 }] };
        }),
      removeItem: (variantId) =>
        set((state) => ({
          items: state.items.filter((i) => i.variantId !== variantId),
        })),
      updateQuantity: (variantId, quantity) =>
        set((state) => ({
          items: quantity <= 0
            ? state.items.filter((i) => i.variantId !== variantId)
            : state.items.map((i) =>
                i.variantId === variantId ? { ...i, quantity } : i
              ),
        })),
      clearCart: () => set({ items: [] }),
      total: () =>
        get().items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    }),
    { name: "cart-storage" }
  )
);

// src/app/api/checkout/route.ts
import { NextRequest, NextResponse } from "next/server";
import Stripe from "stripe";

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!);

export async function POST(req: NextRequest) {
  const { items } = await req.json();

  if (!items?.length) {
    return NextResponse.json({ error: "Cart is empty" }, { status: 400 });
  }

  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    payment_method_types: ["card"],
    shipping_address_collection: {
      allowed_countries: ["US", "CA", "GB", "AU"],
    },
    line_items: items.map((item: any) => ({
      price_data: {
        currency: "usd",
        product_data: {
          name: `${item.title} - ${item.variantTitle}`,
          images: item.image ? [item.image] : [],
        },
        unit_amount: Math.round(item.price * 100),
      },
      quantity: item.quantity,
    })),
    success_url: `${process.env.NEXT_PUBLIC_URL}/checkout/success?session_id={CHECKOUT_SESSION_ID}`,
    cancel_url: `${process.env.NEXT_PUBLIC_URL}/cart`,
  });

  return NextResponse.json({ url: session.url });
}

// src/components/SearchBar.tsx
"use client";
import { useRouter, useSearchParams } from "next/navigation";
import { useState, useTransition } from "react";

export function SearchBar() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [isPending, startTransition] = useTransition();
  const [query, setQuery] = useState(searchParams.get("q") ?? "");

  function handleSearch(e: React.FormEvent) {
    e.preventDefault();
    startTransition(() => {
      const params = new URLSearchParams(searchParams.toString());
      if (query) {
        params.set("q", query);
      } else {
        params.delete("q");
      }
      router.push(`/products?${params.toString()}`);
    });
  }

  return (
    <form onSubmit={handleSearch} className="mb-8">
      <div className="flex gap-2">
        <input
          type="search"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Search products..."
          className="flex-1 rounded-lg border px-4 py-2"
        />
        <button
          type="submit"
          className="rounded-lg bg-black px-6 py-2 text-white"
          disabled={isPending}
        >
          {isPending ? "Searching..." : "Search"}
        </button>
      </div>
    </form>
  );
}
